#include <stdio.h>
#include <stdlib.h>

#define MAX_N 90  // largest n for which fib(n) fits in signed 64‑bit

static long long memo[MAX_N + 1];
static int computed[MAX_N + 1];

static long long fib(int n) {
    if (n == 0) return 0;
    if (n == 1) return 1;
    if (computed[n]) return memo[n];
    long long a = fib(n - 1);
    long long b = fib(n - 2);
    memo[n] = a + b;
    computed[n] = 1;
    return memo[n];
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long val = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (val < 0) {
        puts("NEGATIVE");
        return 0;
    }
    if (val > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long long result = fib((int)val);
    printf("%lld\n", result);
    return 0;
}
